1	// Entry point for the scenario CLI. Reads a scenario JSON from stdin, writes
2	// results to stdout, and reports rejections on stderr with a non-zero status.
3	import type { Scenario } from "./scenario.js";
4	import { runScenario } from "./scenario.js";
5	
6	const readStdin = async (): Promise<string> => {
7	  const chunks: string[] = [];
8	  process.stdin.setEncoding("utf8");
9	  for await (const chunk of process.stdin) {
10	    chunks.push(chunk as string);
11	  }
12	  return chunks.join("");
13	};
14	
15	// The success path, start to finish. It is named for the work it does rather
16	// than for being the entry point, so that the try/catch below reads as the one
17	// thing it adds: a rejected scenario is a failed run, not an empty one.
18	const runScenarioFromStdin = async (): Promise<void> => {
19	  const input = await readStdin();
20	  const scenario = JSON.parse(input) as Scenario;
21	  const results = runScenario(scenario);
22	  process.stdout.write(`${JSON.stringify({ results })}\n`);
23	};
24	
25	try {
26	  await runScenarioFromStdin();
27	} catch (error) {
28	  process.stderr.write(`${(error as Error).message}\n`);
29	  process.exitCode = 1;
30	}
