8	// The CLI's contract is about a process: what it writes to each stream and the
9	// status it exits with. Asserting that by calling a function would only test a
10	// stand-in, so these tests spawn the real entry point and feed it stdin.
11	type CliRun = {
12	  stdout: string;
13	  stderr: string;
14	  code: number;
15	};
16	
17	const runCli = (input: string): Promise<CliRun> =>
18	  new Promise((resolve) => {
19	    const child = execFile(
20	      "npx",
21	      ["tsx", "src/cli.ts"],
22	      (error, stdout, stderr) => {
23	        resolve({
24	          stdout,
25	          stderr,
26	          code: error && typeof error.code === "number" ? error.code : 0,
27	        });
28	      },
29	    );
30	    child.stdin?.end(input);
31	  });
32	
33	const runCliOn = (scenario: Scenario): Promise<CliRun> =>
34	  runCli(JSON.stringify(scenario));
